import{_ as e,o as n,c as t,a3 as o}from"./chunks/framework.I6s8z2kk.js";const p=JSON.parse('{"title":"Account, favorites and ratings","description":"","frontmatter":{},"headers":[],"relativePath":"user/client/account.md","filePath":"user/client/account.md"}'),r={name:"user/client/account.md"};function i(s,a,c,h,u,d){return n(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="account-favorites-and-ratings" tabindex="-1">Account, favorites and ratings <a class="header-anchor" href="#account-favorites-and-ratings" aria-label="Permalink to &quot;Account, favorites and ratings&quot;">​</a></h1><h2 id="signing-in" tabindex="-1">Signing in <a class="header-anchor" href="#signing-in" aria-label="Permalink to &quot;Signing in&quot;">​</a></h2><p>Enter your phone number and the code sent to you. There is no password. A limited number of codes can be sent per phone and per period; if you hit the limit, wait a few minutes.</p><p>First time? You are asked for your <strong>first and last name</strong>. You can change them later in <strong>Profile</strong>.</p><h2 id="changing-your-phone-number" tabindex="-1">Changing your phone number <a class="header-anchor" href="#changing-your-phone-number" aria-label="Permalink to &quot;Changing your phone number&quot;">​</a></h2><p>In <strong>Profile</strong> you can change your phone number. Enter the new number and the code sent to it. The number must not be used by another account. You stay signed in, and you use the new number the next time you sign in.</p><h2 id="purchases" tabindex="-1">Purchases <a class="header-anchor" href="#purchases" aria-label="Permalink to &quot;Purchases&quot;">​</a></h2><p><strong>Purchases</strong> lists everything you bought, newest first, and can be filtered by status. Open a purchase to see its items, discount, total and payment status.</p><h2 id="favorites" tabindex="-1">Favorites <a class="header-anchor" href="#favorites" aria-label="Permalink to &quot;Favorites&quot;">​</a></h2><p>Tap the heart on a center to save it. <strong>Favorites</strong> lists them. Tap again to remove.</p><h2 id="ratings" tabindex="-1">Ratings <a class="header-anchor" href="#ratings" aria-label="Permalink to &quot;Ratings&quot;">​</a></h2><p>After visiting, you can <strong>rate</strong> a center. Ratings help other clients and influence popular centers on the home screen.</p><p><strong>My ratings</strong> lists the ratings you gave, newest first or highest first. You can change the stars or the comment of any of them.</p><h2 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h2><p>Your notification inbox shows booking updates and offers. You can mark one or all as read. Push notifications arrive in your app&#39;s language.</p><h2 id="privacy-policy-and-terms" tabindex="-1">Privacy policy and terms <a class="header-anchor" href="#privacy-policy-and-terms" aria-label="Permalink to &quot;Privacy policy and terms&quot;">​</a></h2><p>The app links to the Khyyal privacy policy and terms and conditions. They open inside the app in your language.</p>',17)])])}const g=e(r,[["render",i]]);export{p as __pageData,g as default};
